/* Original educational content asset: five English and five Business lessons.
 * Load after learning-data.js and before learning-engine.js; registration only.
 * Existing IDs are enriched by the engine, which appends their new questions.
 * All passages, models, businesses and numerical datasets below are fictional originals.
 * References support only the context/topic named, never the invented cases or results.
 * checked preserves the source-verification date supplied by the project owner.
 */
(()=>{
  const L=IBLearning.L;
  IBLearning.expansions=(IBLearning.expansions||[]).concat([
    {
      course:'english',id:'english-opinion',
      title:L('Opinar, ejemplificar y matizar al hablar','Speaking: opinion, example and qualification'),
      intro:L('Practica una intervención breve y revisa la relación entre tu ejemplo y el alcance de tu opinión. La autoevaluación es una reflexión personal sobre tu intento.','Practise a short contribution and review how your example relates to the scope of your opinion. Self-review is your own reflection on your attempt.'),
      keywords:'english speaking opinión opinion ejemplo example qualification matizar self review autoevaluación oral',difficulty:'intermediate',
      goals:['Conectar un ejemplo con una razón explícita.','Reducir una generalización mediante una condición relevante.','Revisar una intervención con criterios observables.'],
      prerequisites:'Poder expresar preferencias y explicar una razón sencilla en inglés.',
      sections:[
        {title:'Delimitar antes de intervenir',body:'Una conversación mejora cuando tu postura responde a una pregunta concreta. Antes de hablar, decide si estás recomendando una medida para un grupo, comparando alternativas o describiendo una preferencia personal. Estas tareas requieren alcances distintos. En una propuesta sobre horarios, identifica quién tendría que adaptarse. Usa una nota con palabras clave para conservar el hilo; redactar cada frase puede dificultar responder a una objeción inesperada.'},
        {title:'Hacer que el ejemplo trabaje',body:'Después del ejemplo, explica qué relación tiene con tu razón. Un episodio donde alguien pudo participar muestra una posibilidad, pero no demuestra que todas las personas participarían. Pregunta qué elemento del episodio resulta transferible: el horario, el espacio o la ayuda disponible. Si el ejemplo es inventado, preséntalo como una situación imaginada. Así puedes practicar razonamiento oral sin convertir una ficción didáctica en una experiencia personal supuestamente vivida.'},
        {title:'Matizar y revisar con un propósito',body:'Una condición útil cambia el alcance de la recomendación. No basta añadir una expresión de duda al final. Indica cuándo sería menos conveniente la medida y qué adaptación propondrías. Tras ensayar, reconstruye tus ideas en tres notas: postura, vínculo explicativo y condición. Revisa si respondiste a la pregunta y si podrías aclarar un término sin reiniciar todo. Esta actividad requiere tu propia observación; no proporciona evaluación automática de pronunciación ni de fluidez.'}
      ],
      example:{title:'Modelo oral original: club ficticio de lectura',body:'Situación ficticia: un club considera trasladar su reunión a la hora del almuerzo. Modelo original: “I would try a lunchtime reading group. For example, a student who takes an early bus home could attend. This would remove one scheduling barrier. However, it would only help if students still had enough time to eat.” La primera frase propone una prueba limitada. El ejemplo identifica a una persona posible, sin afirmar que exista una encuesta. La tercera frase explica el mecanismo: reducir una barrera de horario. La última introduce una condición que podría obligar a acortar la reunión. Al revisar, comprueba que el beneficio y la limitación se refieren a la misma propuesta.'},
      extension:'Responde a esta objeción imaginada: algunas personas usan el almuerzo para descansar. Conserva tu propósito, pero modifica duración o frecuencia. Ensaya después una versión con una condición distinta y decide cuál afecta más a tu recomendación. Anota qué frase cambiarías y por qué; una revisión específica resulta más útil que describir todo el intento como bueno o malo.',
      mistakes:['Presentar una situación inventada como recuerdo propio: anunciar que es hipotética.','Añadir una condición desconectada: explicar cómo modificaría la propuesta.'],
      glossary:[['Qualification','Condición o límite que precisa el alcance de una afirmación.'],['Self-review','Revisión personal del intento mediante criterios explícitos.']],
      refs:[{name:'British Council · Free resources (contexto de práctica de habilidades; modelo original)',url:'https://learnenglish.britishcouncil.org/free-resources',scope:'context',checked:'2026-10-17'}],
      quiz:[
        {text:L('¿Qué función cumple la referencia al autobús?','What does the reference to the bus do?'),options:[L('Prueba que todos prefieren el almuerzo.','It proves everyone prefers lunchtime.'),L('Ilustra una barrera que el horario podría reducir.','It illustrates a barrier the schedule could reduce.'),L('Demuestra que el club ya tuvo éxito.','It proves the club has already succeeded.')],answer:1,why:L('El caso hipotético conecta horario y acceso, sin medir resultados.','The hypothetical case links scheduling and access without measuring outcomes.'),optionWhy:[L('Un caso posible no representa todas las preferencias.','One possible case does not represent every preference.'),L('El transporte limita la participación después de clase.','Transport limits participation after lessons.'),L('La propuesta todavía no se ha probado.','The proposal has not been tested yet.')]},
        {text:L('¿Qué respuesta atiende la objeción sobre descansar?','Which response addresses the objection about rest?'),options:[L('Ensayar reuniones más cortas una vez por semana.','Try shorter meetings once a week.'),L('Repetir que leer siempre es bueno.','Repeat that reading is always good.'),L('Describir el color de los libros.','Describe the colour of the books.')],answer:0,why:L('Reducir duración y frecuencia responde al uso del tiempo disponible.','Reducing length and frequency addresses the use of available time.'),optionWhy:[L('Introduce un ajuste que puede compararse con el plan inicial.','It introduces an adjustment that can be compared with the initial plan.'),L('Defiende la actividad sin resolver la dificultad de horario.','It defends the activity without resolving the scheduling problem.'),L('El color no afecta al descanso en este caso.','Colour does not affect rest in this case.')]},
        {text:L('¿Qué nota ofrece una autoevaluación específica?','Which note provides specific self-review?'),options:[L('Mi inglés fue perfecto.','My English was perfect.'),L('Hablé y por eso todos estuvieron de acuerdo.','I spoke, so everyone agreed.'),L('Expliqué el horario, pero debo aclarar la condición sobre comer.','I explained the schedule, but I need to clarify the condition about eating.')],answer:2,why:L('Identifica una parte del argumento que puede revisarse.','It identifies a part of the argument that can be revised.'),optionWhy:[L('Es una valoración global sin criterio observable.','It is a global judgement without an observable criterion.'),L('Hablar no demuestra acuerdo de la audiencia.','Speaking does not establish audience agreement.'),L('Relaciona la revisión con una frase concreta del intento.','It ties revision to a specific part of the attempt.')]}
      ],
      practice:{prompt:L('Ensaya en inglés una propuesta para el club ficticio y realiza una autoevaluación escrita.','Rehearse a proposal in English for the fictional club and write a self-review.'),steps:[L('Elige un horario y prepara tres palabras clave.','Choose a time and prepare three keywords.'),L('Habla durante aproximadamente un minuto: explica un ejemplo y una condición.','Speak for about a minute: explain an example and a condition.'),L('Escribe de memoria una frase que quieras mejorar y ensaya su revisión.','Write from memory one sentence you want to improve and rehearse the revision.')],checks:[L('Identifiqué mi ejemplo como hipotético y expliqué su relevancia.','I identified my example as hypothetical and explained its relevance.'),L('Mi condición podría modificar realmente la propuesta.','My condition could actually change the proposal.'),L('Mi revisión describe lo que observé personalmente.','My review describes what I observed myself.')]}
    },
    {
      course:'english',id:'english-evidence',
      title:L('Interpretar un microextracto original','Interpreting an original microextract'),
      intro:L('Analiza una imagen y un contraste temporal en un texto literario original. Separa las palabras del fragmento, tu inferencia y una lectura alternativa.','Analyse an image and a temporal contrast in an original literary text. Separate the extract’s words, your inference and an alternative reading.'),
      keywords:'english evidence literary extract microextracto imagen contrast inference interpretación literatura',difficulty:'intermediate',
      goals:['Relacionar una elección verbal con un efecto posible.','Distinguir inferencia y hecho narrado.','Comparar dos interpretaciones compatibles con detalles concretos.'],
      prerequisites:'Comprender una narración breve en pasado y reconocer comparaciones sencillas en inglés.',
      sections:[
        {title:'Leer acciones antes de interpretar',body:'Lee el microextracto completo del ejemplo y enumera sus acciones: una persona pinta un nombre, otra toca las letras y mantiene el abrigo puesto. Este inventario ayuda a localizar aquello que la narración sí presenta. Luego separa lo que falta: no sabemos por qué llegaron, cuánto tiempo permanecerán ni qué relación familiar tienen. Una interpretación precisa puede ser interesante sin rellenar esos vacíos con una historia que el texto nunca cuenta.'},
        {title:'Examinar la imagen y el contraste',body:'La comparación de las letras con una temperatura convierte un signo visual en una experiencia corporal. Tocar el nombre puede sugerir búsqueda de familiaridad, aunque también admite curiosidad. El contraste entre una acción realizada ayer y una espera todavía presente conecta dos momentos. Explica cómo esas elecciones podrían representar una llegada incompleta: el nombre ocupa ya un lugar, mientras la persona sigue preparada para marcharse. La interpretación surge de relacionar detalles, no de nombrar recursos aislados.'},
        {title:'Graduar la certeza del comentario',body:'En inglés, puedes usar suggests para proponer un efecto y may para reconocer incertidumbre. El comentario debe identificar quién percibe o actúa: una narración en tercera persona no garantiza acceso a todos los pensamientos. Evita atribuir una intención comprobada a un autor real, porque el pasaje fue creado para esta actividad. Para revisar tu lectura, busca un detalle que admita otra explicación y decide cuánto reduce la seguridad de tu conclusión inicial.'}
      ],
      example:{title:'Microextracto literario original y ficticio: el nombre',body:'Texto original en inglés: “Yesterday, Mara painted her name on the new mailbox. Today, her brother touched the letters as if checking their temperature. Behind him, the house stood open. He kept his coat on.” Una lectura posible relaciona el nombre con pertenencia y el abrigo con una disposición provisional. La puerta abierta ofrece acceso físico, pero no confirma comodidad emocional. Otra lectura atribuiría el abrigo al frío. Esta alternativa debilita una conclusión tajante sobre rechazo del hogar, aunque no elimina el contraste entre marcar un lugar y mantenerse listo para salir. No conocemos una temperatura real: la comparación no funciona como informe meteorológico.'},
      extension:'Redacta dos frases analíticas en inglés y conserva solo las citas mínimas necesarias. Después sustituye mentalmente el abrigo por una mochila guardada en un armario. Explica cómo cambiaría tu interpretación y qué detalle seguiría sosteniéndola. Esta comparación examina la contribución de una elección narrativa, sin afirmar que todos los lectores tengan una reacción idéntica.',
      mistakes:['Deducir una mudanza forzada sin evidencia: conservar abiertas las causas de la llegada.','Tratar la temperatura figurada como dato climático: explicar la comparación.'],
      glossary:[['Inference','Conclusión razonada que va más allá de lo expresamente narrado.'],['Temporal contrast','Relación entre momentos que permite percibir cambio, continuidad o demora.']],
      refs:[{name:'British Council · Free resources (contexto de aprendizaje del inglés; no fuente del microextracto)',url:'https://learnenglish.britishcouncil.org/free-resources',scope:'context',checked:'2026-10-17'}],
      quiz:[
        {text:L('¿Qué detalle sostiene una disposición provisional?','Which detail supports a sense of provisional readiness?'),options:[L('El hermano conserva el abrigo puesto.','The brother keeps his coat on.'),L('Mara declara que odia la casa.','Mara says she hates the house.'),L('La narración explica una expulsión.','The narration explains an eviction.')],answer:0,why:L('El abrigo admite una lectura de preparación para salir, aunque no la prueba definitivamente.','The coat allows a reading of readiness to leave, although it does not prove it conclusively.'),optionWhy:[L('Es un detalle presente que puede conectarse con la interpretación.','It is a detail in the text that can support the interpretation.'),L('Mara no habla en el fragmento.','Mara does not speak in the extract.'),L('No se explica ninguna expulsión.','No eviction is explained.')]},
        {text:L('¿Qué limita la lectura del abrigo como incomodidad?','What limits reading the coat as discomfort?'),options:[L('El texto confirma que es verano.','The text confirms it is summer.'),L('La casa no tiene puerta.','The house has no door.'),L('También podría llevarlo por frío.','He might also wear it because he is cold.')],answer:2,why:L('La misma acción admite un motivo alternativo que no está resuelto.','The same action allows an alternative motive that remains unresolved.'),optionWhy:[L('No se indica ninguna estación.','No season is given.'),L('La casa aparece abierta; no se describe ausencia de puerta.','The house stands open; the absence of a door is not described.'),L('Es una posibilidad compatible, no un nuevo hecho demostrado.','It is a compatible possibility, not a newly established fact.')]},
        {text:L('¿Qué comentario analiza la comparación de las letras?','Which comment analyses the comparison involving the letters?'),options:[L('Prueba que las letras tienen fiebre.','It proves the letters have a fever.'),L('Convierte el contacto con un nombre en una búsqueda corporal de familiaridad.','It turns contact with a name into a bodily search for familiarity.'),L('El autor real confirmó su significado en una entrevista.','The real author confirmed its meaning in an interview.')],answer:1,why:L('Propone un efecto de la imagen vinculando signo y sensación.','It proposes an effect of the image by connecting sign and sensation.'),optionWhy:[L('Interpreta literalmente una comparación.','It interprets a comparison literally.'),L('Explica una relación expresiva que puede defenderse con el pasaje.','It explains an expressive relationship that can be defended using the passage.'),L('No se proporciona tal entrevista; el texto es original de esta actividad.','No such interview is provided; the text is original to this activity.')]}
      ],
      practice:{prompt:L('Escribe en inglés un comentario de 70–100 palabras sobre pertenencia en el microextracto ficticio.','Write a 70–100-word commentary in English on belonging in the fictional microextract.'),steps:[L('Selecciona dos detalles y explica cómo se relacionan.','Select two details and explain how they relate.'),L('Propón una interpretación con suggests o may.','Propose an interpretation using suggests or may.'),L('Añade una lectura alternativa y precisa qué sigue siendo defendible.','Add an alternative reading and specify what remains defensible.')],checks:[L('Mis citas aparecen exactamente en el microextracto.','My quotations appear exactly in the microextract.'),L('No añadí una biografía, clima o motivo como si fueran hechos narrados.','I did not add a biography, weather or motive as if they were narrated facts.')]}
    },
    {
      course:'english',id:'english-reading',
      title:L('Leer propósito, condiciones e inferencias','Reading purpose, conditions and inferences'),
      intro:L('Lee un aviso original en inglés para distinguir una invitación de una garantía. Recupera detalles y relaciona pronombres, límites y propósito.','Read an original notice in English to distinguish an invitation from a guarantee. Retrieve details and connect pronouns, limits and purpose.'),
      keywords:'english reading comprehension lectura scanning skimming purpose inference pronouns conditions',difficulty:'foundation',
      goals:['Identificar el propósito de un aviso.','Recuperar condiciones explícitas sin generalizar.','Resolver una referencia pronominal mediante el contexto.'],
      prerequisites:'Reconocer días, horarios y expresiones básicas de posibilidad en inglés.',
      sections:[
        {title:'Una primera lectura orientada al propósito',body:'Antes de traducir palabra por palabra, identifica qué quiere que haga el lector: informarse, reservar, comparar o cambiar una conducta. El aviso del ejemplo combina invitación e instrucciones. Su público probable son personas interesadas en reparar objetos pequeños, pero esa inferencia no autoriza a afirmar que todas tienen conocimientos técnicos. Una primera lectura debe producir una idea global provisional; la segunda comprueba los detalles que podrían modificarla.'},
        {title:'Buscar restricciones que cambian la decisión',body:'Localiza cantidades, horarios y negaciones. Una restricción suele ser más importante para actuar que una expresión entusiasta. En este aviso, reservar un lugar no equivale a asegurar una reparación. Separa el beneficio ofrecido de los límites del servicio y registra ambos en tus notas. Si una pregunta contiene siempre o todos, vuelve al texto: esas palabras suelen ampliar indebidamente una afirmación que originalmente era condicional o limitada.'},
        {title:'Inferir sin sustituir información ausente',body:'Resuelve las referencias mediante concordancia y sentido. El pronombre them del aviso remite a los recipientes, porque son los objetos que pueden etiquetarse. Una inferencia sobre el propósito de esas etiquetas puede ser razonable, pero no es una instrucción textual adicional. Al responder, distingue entre está escrito, se puede inferir y no se sabe. Esta clasificación evita que una explicación plausible termine presentada como una condición obligatoria del organizador.'}
      ],
      example:{title:'Lectura original: aviso de un taller ficticio',body:'Aviso original en inglés: “The Saturday Repair Table opens at ten. Visitors may bring one small household item, but volunteers cannot promise a repair. Book a place by Thursday; walk-ins will be accepted only if space remains. Bring a container for loose parts and label it with your initials. Spare containers are available at the desk. Please label them before use. The session ends at noon, even if work is unfinished.” El aviso busca organizar una visita, no vender una reparación garantizada. Quien llegue sin reserva depende del espacio restante. La referencia them apunta a los recipientes de repuesto; la frase anterior proporciona el antecedente. Terminar al mediodía tampoco significa que todo objeto quede reparado: el cierre limita el tiempo disponible.'},
      extension:'Escribe tres respuestas en inglés: una sobre una condición explícita, otra sobre un propósito inferido y otra sobre algo desconocido. Para esta última, formula una pregunta que enviarías a la organización, por ejemplo sobre tipos de objetos aceptados. No conviertas tu pregunta en una nueva regla del aviso; conserva clara la diferencia entre información disponible e información solicitada.',
      mistakes:['Confundir reserva con reparación garantizada: revisar el alcance de cada promesa.','Elegir el antecedente solo por cercanía: comprobar también qué acción tiene sentido.'],
      glossary:[['Walk-in','Persona que llega sin reserva previa.'],['Antecedent','Palabra o grupo al que remite un pronombre.'],['Scanning','Lectura selectiva para localizar un dato concreto.']],
      refs:[{name:'British Council · Free resources (contexto para practicar lectura; aviso original)',url:'https://learnenglish.britishcouncil.org/free-resources',scope:'context',checked:'2026-10-17'}],
      quiz:[
        {text:L('¿Cuándo se acepta a alguien sin reserva?','When is a walk-in accepted?'),options:[L('Siempre que llegue antes del jueves.','Whenever they arrive before Thursday.'),L('Solo si queda espacio.','Only if space remains.'),L('Únicamente después del mediodía.','Only after noon.')],answer:1,why:L('El aviso condiciona la entrada sin reserva a la capacidad disponible.','The notice makes walk-in entry conditional on available capacity.'),optionWhy:[L('El jueves es el plazo de reserva, no el día de llegada.','Thursday is the booking deadline, not the arrival day.'),L('Reproduce la condición explícita del aviso.','It matches the notice’s explicit condition.'),L('La sesión termina al mediodía.','The session ends at noon.')]},
        {text:L('¿A qué remite them en Please label them?','What does them refer to in Please label them?'),options:[L('Los recipientes de repuesto.','The spare containers.'),L('Los voluntarios.','The volunteers.'),L('Los jueves.','Thursdays.')],answer:0,why:L('Los recipientes son el antecedente plural compatible con etiquetar.','The containers are the plural antecedent compatible with labelling.'),optionWhy:[L('Concuerda con la frase anterior y la acción solicitada.','It matches the previous sentence and requested action.'),L('El aviso no pide etiquetar personas.','The notice does not ask anyone to label people.'),L('Un día no es el objeto que se etiqueta aquí.','A day is not the object being labelled here.')]},
        {text:L('¿Qué afirmación no puede confirmarse con el aviso?','Which statement cannot be confirmed from the notice?'),options:[L('La sesión comienza a las diez.','The session starts at ten.'),L('Se permite un objeto pequeño por visitante.','One small item per visitor is allowed.'),L('Todas las reparaciones son gratuitas.','All repairs are free.')],answer:2,why:L('No se ofrece información sobre precios.','No pricing information is provided.'),optionWhy:[L('La hora de apertura está indicada.','The opening time is stated.'),L('La cantidad y el tamaño aparecen expresamente.','The number and size are explicitly stated.'),L('La presencia de voluntarios no demuestra gratuidad.','The presence of volunteers does not establish that repairs are free.')]}
      ],
      practice:{prompt:L('Resume en inglés cómo prepararse para el taller ficticio y qué sigue sin saberse.','Summarise in English how to prepare for the fictional workshop and what remains unknown.'),steps:[L('Localiza el plazo de reserva, el límite de objetos y la hora de cierre.','Locate the booking deadline, item limit and closing time.'),L('Explica una condición usando only if.','Explain one condition using only if.'),L('Añade una pregunta cuya respuesta no aparezca en el aviso.','Add a question whose answer is not in the notice.')],checks:[L('Mi resumen mantiene la diferencia entre entrada y reparación.','My summary preserves the difference between entry and repair.'),L('He separado una inferencia de los datos expresos.','I have separated an inference from explicit details.')]}
    },
    {
      course:'english',id:'english-writing',
      title:L('Escribir una solicitud con un modelo anotado','Writing a request with an annotated model'),
      intro:L('Adapta propósito, registro y organización a un correo de solicitud. Examina un modelo original y revisa qué información necesita su destinatario.','Adapt purpose, register and organisation to a request email. Examine an original model and review what information its recipient needs.'),
      keywords:'english writing email register audience request escritura correo modelo anotado revisión cohesion',difficulty:'intermediate',
      goals:['Organizar una solicitud según las necesidades del destinatario.','Elegir un registro cortés y preciso.','Revisar contenido antes de corregir detalles superficiales.'],
      prerequisites:'Poder escribir oraciones sencillas en inglés con presente y futuro.',
      sections:[
        {title:'Decidir qué respuesta necesitas',body:'Un correo eficaz permite al destinatario identificar la acción solicitada. Antes de escribir, anota quién recibe el mensaje, qué relación tienes con esa persona y qué decisión esperas. Si necesitas permiso para usar una sala, incluye fecha, duración y condiciones relevantes. No añadas una historia extensa que esconda la solicitud. Tampoco presentes el permiso como concedido: el lenguaje debe representar correctamente el estado de la propuesta.'},
        {title:'Organizar y ajustar el registro',body:'Distribuye las funciones del mensaje: saludo, propósito, información necesaria, pregunta y cierre. El registro cortés combina claridad y respeto; no exige palabras rebuscadas ni disculpas en cada oración. Una pregunta con could puede solicitar información sin imponerla. En cambio, una orden puede resultar inadecuada cuando la otra persona administra recursos compartidos. Los conectores deben mostrar relaciones reales entre las ideas, no decorar párrafos que todavía carecen de una secuencia comprensible.'},
        {title:'Revisar del contenido a la forma',body:'Primero comprueba si el destinatario podría responder con los datos disponibles. Después revisa consistencia: un grupo de ocho personas no debe convertirse accidentalmente en doce. Finalmente observa tiempos verbales, puntuación y despedida. Leer cada oración preguntando qué función cumple permite eliminar repeticiones. Una revisión útil explica por qué una modificación facilita la respuesta, en lugar de sustituir palabras sencillas por sinónimos más largos sin mejorar el mensaje.'}
      ],
      example:{title:'Correo original anotado: solicitud ficticia de sala',body:'Modelo original en inglés: “[1] Dear Ms Reed, [2] I am writing to ask whether our reading group could use Room 4 on Tuesday from 4 to 5 p.m. [3] Eight students plan to attend, and we would leave the room tidy. [4] Could you let us know whether the room is available and whether we need a staff supervisor? [5] Thank you for considering our request. Best wishes, Alex.” Las marcas son anotaciones didácticas, no parte del correo que enviarías. [1] establece un trato cortés; [2] expone solicitud, lugar y horario; [3] aporta escala y responsabilidad; [4] permite resolver disponibilidad y supervisión; [5] cierra sin presuponer autorización. La fecha exacta podría añadirse para evitar confusión sobre qué martes se solicita.'},
      extension:'Reescribe el mensaje para un compañero que organiza el grupo. Conserva los hechos, cambia el registro y explica qué información ahora sería prioritaria. Después vuelve al correo formal y añade una alternativa de horario claramente condicional. Comprueba que la alternativa facilita decidir sin crear dos reservas supuestamente confirmadas. Usa el modelo como estructura de aprendizaje, no como experiencia personal realizada.',
      mistakes:['Copiar las marcas de anotación como parte del correo: retirarlas del borrador final.','Dar por confirmada la sala mientras solicitas permiso: mantener el lenguaje condicional.'],
      glossary:[['Register','Grado y tipo de formalidad apropiado para una situación comunicativa.'],['Purpose','Resultado comunicativo que busca el texto.'],['Revision','Revisión razonada de contenido, organización y expresión.']],
      refs:[{name:'British Council · Free resources (contexto de práctica escrita; correo original anotado)',url:'https://learnenglish.britishcouncil.org/free-resources',scope:'context',checked:'2026-10-17'}],
      quiz:[
        {text:L('¿Qué aporta principalmente la parte [3]?','What does part [3] mainly contribute?'),options:[L('Una autorización definitiva.','Definite permission.'),L('Una amenaza si la sala no está libre.','A threat if the room is unavailable.'),L('Información sobre tamaño del grupo y cuidado del espacio.','Information about group size and care of the space.')],answer:2,why:L('Ayuda a valorar la solicitud mediante datos relevantes.','It helps assess the request through relevant information.'),optionWhy:[L('Quien escribe todavía está solicitando permiso.','The writer is still requesting permission.'),L('La frase ofrece responsabilidad, no amenaza.','The sentence offers responsibility, not a threat.'),L('Ocho asistentes y dejar ordenada la sala orientan la decisión.','Eight attendees and leaving the room tidy inform the decision.')]},
        {text:L('¿Qué revisión reduce una ambigüedad temporal?','Which revision reduces temporal ambiguity?'),options:[L('Añadir la fecha exacta del martes solicitado.','Add the exact date of the requested Tuesday.'),L('Eliminar el horario.','Delete the time.'),L('Cambiar ocho estudiantes por mucha gente.','Replace eight students with lots of people.')],answer:0,why:L('Una fecha concreta permite identificar la reserva solicitada.','A specific date identifies the requested booking.'),optionWhy:[L('Aclara un dato necesario sin cambiar el propósito.','It clarifies a necessary detail without changing the purpose.'),L('Eliminaría información útil para decidir.','It would remove information needed for the decision.'),L('Reduce precisión sobre asistentes, no sobre fechas.','It reduces attendee precision rather than clarifying dates.')]},
        {text:L('¿Qué frase presupone indebidamente autorización?','Which sentence improperly assumes permission?'),options:[L('Could we use the room?','Could we use the room?'),L('Thank you for approving our booking.','Thank you for approving our booking.'),L('Is a supervisor required?','Is a supervisor required?')],answer:1,why:L('Agradecer una aprobación afirma que ya ocurrió.','Thanking someone for approval states that it has already happened.'),optionWhy:[L('Formula una solicitud abierta.','It makes an open request.'),L('No existe aprobación en los hechos del caso.','There is no approval in the case facts.'),L('Solicita una condición que todavía se desconoce.','It asks about a condition that is still unknown.')]}
      ],
      practice:{prompt:L('Escribe un correo original en inglés de 90–120 palabras solicitando una sala para una actividad ficticia distinta.','Write an original 90–120-word email in English requesting a room for a different fictional activity.'),steps:[L('Define destinatario, fecha, horario, asistentes y respuesta necesaria.','Define the recipient, date, time, attendees and response needed.'),L('Redacta una solicitud cortés y una pregunta sobre condiciones.','Draft a polite request and a question about conditions.'),L('Anota la función de cada parte y elimina las marcas del texto final.','Annotate each part’s function and remove the marks from the final text.')],checks:[L('El destinatario tiene información suficiente para responder.','The recipient has enough information to reply.'),L('La solicitud no afirma una aprobación que todavía no existe.','The request does not claim approval that does not yet exist.')]}
    },
    {
      course:'english',id:'english-vocabulary',
      title:L('Vocabulario, colocaciones y conectores','Vocabulary, collocations and connectors'),
      intro:L('Elige expresiones por su función y contexto. Practica combinaciones naturales y distingue causa, consecuencia, contraste y concesión.','Choose expressions by function and context. Practise natural combinations and distinguish cause, consequence, contrast and concession.'),
      keywords:'english vocabulary connectors collocations vocabulario conectores because therefore however although make decision',difficulty:'foundation',
      goals:['Aprender palabras junto con sus combinaciones frecuentes.','Seleccionar un conector según la relación lógica.','Revisar gramática y significado al sustituir expresiones.'],
      prerequisites:'Reconocer sujeto y verbo en oraciones sencillas en inglés.',
      sections:[
        {title:'Guardar expresiones completas',body:'Aprender una palabra aislada no siempre permite usarla con naturalidad. Registra una combinación, una situación y una frase propia. Para hablar de decisiones puedes guardar make a decision; para expresar un problema, raise a concern. Observa qué verbo acompaña al sustantivo y qué información necesita después. La traducción literal puede ayudarte a recordar el sentido, pero no garantiza que una combinación resultante sea habitual en inglés.'},
        {title:'Elegir la relación antes del conector',body:'Escribe primero las dos ideas sin unión y decide cómo se relacionan. Because presenta una razón; therefore introduce una consecuencia; however señala contraste. Aunque dos frases aparezcan una después de otra, no necesariamente existe causalidad entre ellas. Si desconoces por qué ocurrió algo, un conector causal puede inventar una explicación. En la revisión, sustituye mentalmente el conector por una descripción de su función y comprueba si esa relación realmente está justificada.'},
        {title:'Cambiar la estructura junto con la palabra',body:'Although introduce una cláusula subordinada, mientras however puede enlazar dos oraciones independientes mediante puntuación apropiada. No basta intercambiarlos y conservar todas las comas. Practica primero con oraciones breves que mantengan un mismo significado. También revisa intensidad: replacing always with often cambia la frecuencia afirmada, no solo el estilo. Un vocabulario más preciso ayuda a representar los datos disponibles y evita que una frase elegante exagere una conclusión.'}
      ],
      example:{title:'Minihistoria original: decisión ficticia sobre un cartel',body:'Texto original en inglés: “The team had to make a decision about its poster. The first design was attractive. However, the date was difficult to read. Because visitors needed the date, the team enlarged it. The revised version was clearer; therefore, the team chose it.” La combinación make a decision nombra la acción. However contrasta atractivo y legibilidad sin negar que ambas características coexistan. Because introduce la razón del cambio; therefore relaciona la mejora con la elección. Una reformulación posible es “Although the first design was attractive, the date was difficult to read.” Cambia la estructura, pero conserva la concesión. La historia es ficticia y no informa resultados de una campaña real.'},
      extension:'Crea cuatro tarjetas con una expresión, su función y una oración distinta del modelo. En una tarjeta, escribe deliberadamente un conector incorrecto y explica qué relación falsa produce. Después corrígelo sin modificar los hechos. Recupera las expresiones más tarde sin mirar las tarjetas: poder reconocerlas al leer no garantiza poder utilizarlas de manera independiente al escribir.',
      mistakes:['Usar do a decision: aprender la combinación make a decision.','Usar therefore solo porque una frase sigue a otra: justificar una consecuencia.'],
      glossary:[['Collocation','Combinación de palabras que se usa habitualmente en una lengua.'],['Concession','Relación que reconoce un hecho sin eliminar una afirmación contrastante.'],['Connector','Expresión que hace explícita una relación entre ideas.']],
      refs:[{name:'British Council · Free resources (contexto de vocabulario y gramática; ejemplos originales)',url:'https://learnenglish.britishcouncil.org/free-resources',scope:'context',checked:'2026-10-17'}],
      quiz:[
        {text:L('¿Qué combinación completa We need to ___ a decision?','Which combination completes We need to ___ a decision?'),options:[L('do','do'),L('make','make'),L('perform','perform')],answer:1,why:L('La combinación habitual aquí es make a decision.','The usual combination here is make a decision.'),optionWhy:[L('Do no forma la colocación habitual con decision.','Do does not form the usual collocation with decision.'),L('Make se combina con decision para expresar decidir.','Make combines with decision to express deciding.'),L('Perform suele acompañar acciones como una tarea o actuación.','Perform usually accompanies actions such as a task or performance.')]},
        {text:L('¿Qué relación expresa However en el modelo?','What relationship does However express in the model?'),options:[L('La fecha es ilegible porque el cartel es atractivo.','The date is unreadable because the poster is attractive.'),L('Los dos diseños son idénticos.','The two designs are identical.'),L('El atractivo coexiste con una limitación de lectura.','Visual appeal coexists with a readability limitation.')],answer:2,why:L('Contrasta cualidades sin afirmar causalidad.','It contrasts qualities without claiming causality.'),optionWhy:[L('Añade una causa que el texto no establece.','It adds a cause the text does not establish.'),L('No compara los diseños como idénticos.','It does not present the designs as identical.'),L('Conserva el contraste entre aspecto y uso.','It preserves the contrast between appearance and use.')]},
        {text:L('¿Qué reformulación mantiene la concesión y una estructura correcta?','Which rewrite preserves concession and a correct structure?'),options:[L('Although it was attractive, the date was difficult to read.','Although it was attractive, the date was difficult to read.'),L('Although. It was attractive the date.','Although. It was attractive the date.'),L('Therefore it was attractive because.','Therefore it was attractive because.')],answer:0,why:L('Although introduce una cláusula completa seguida de una principal.','Although introduces a complete subordinate clause followed by a main clause.'),optionWhy:[L('La puntuación y las dos cláusulas permiten expresar la relación.','The punctuation and two clauses express the relationship.'),L('El conector queda separado y falta una oración coherente.','The connector is stranded and a coherent sentence is missing.'),L('Because queda sin cláusula y no se conserva el contraste.','Because lacks a clause and the contrast is lost.')]}
      ],
      practice:{prompt:L('Escribe en inglés cinco frases sobre una decisión ficticia utilizando colocaciones y conectores precisos.','Write five sentences in English about a fictional decision using precise collocations and connectors.'),steps:[L('Incluye make a decision y una frase con raise a concern.','Include make a decision and a sentence with raise a concern.'),L('Marca una razón, un contraste y una consecuencia antes de elegir conectores.','Mark a reason, a contrast and a consequence before choosing connectors.'),L('Reformula un contraste con although y revisa su puntuación.','Rewrite one contrast using although and check its punctuation.')],checks:[L('Mis conectores no introducen causas que desconozco.','My connectors do not introduce causes I do not know.'),L('He conservado el significado al cambiar la estructura.','I have preserved meaning when changing the structure.')]}
    }
    ,{
      course:'business',id:'business-segment',
      title:L('Segmentación y posicionamiento con evidencia','Evidence-based segmentation and positioning'),
      intro:L('Compara dos segmentos de una empresa ficticia mediante necesidades, contribución y límites de capacidad. Justifica un posicionamiento que pueda comprobarse.','Compare two segments of a fictional business using needs, contribution and capacity limits. Justify a positioning that can be tested.'),
      keywords:'business marketing segmentación segmentation targeting posicionamiento positioning contribución mercado objetivo',difficulty:'intermediate',
      goals:['Distinguir segmento, mercado objetivo y posicionamiento.','Calcular la contribución prevista de dos ofertas.','Evaluar una selección bajo incertidumbre.'],
      prerequisites:'Calcular porcentajes y distinguir ingresos de costes variables.',
      sections:[
        {title:'Explicar una necesidad compartida',body:'Segmentar consiste en agrupar clientes mediante características relevantes para una decisión comercial. Elegir el mercado objetivo supone decidir a qué grupo atender; posicionar consiste en definir cómo se desea que ese grupo perciba la oferta frente a alternativas. En el taller ficticio Rueda Clara, clasificar por necesidad de reparación urgente puede orientar horarios y disponibilidad de piezas. Clasificar únicamente por edad no explica necesariamente esa necesidad. Para explicar una elección, conecta el rasgo del grupo con una adaptación concreta del servicio y señala cómo comprobarías que esa adaptación resulta valiosa.'},
        {title:'Analizar atractivo y capacidad',body:'Un grupo grande no garantiza una oportunidad rentable. En este ejercicio, estima compradores multiplicando personas alcanzables por una tasa de conversión supuesta; después multiplica compradores por contribución unitaria, es decir, precio menos coste variable. Resta el coste específico de captar ese grupo para comparar campañas. Esta cifra todavía no es beneficio total: quedan costes comunes del taller. Comprueba además cuántos servicios caben en el periodo. Si una previsión supera la capacidad, las ventas no pueden aceptarse sin estudiar esperas, contratación o inversión adicional. Todas las tasas del caso son hipótesis didácticas.'},
        {title:'Evaluar una promesa comercial',body:'Rueda Clara podría prometer un plazo definido de reparación para quienes dependen de su bicicleta a diario, siempre que pueda cumplirlo. Una frase atractiva necesita respaldo operativo: piezas disponibles, personal y un sistema de reservas. Discute el beneficio de concentrar recursos y el riesgo de depender de un solo grupo. Al evaluar, elige un criterio prioritario, compara resultados y formula una condición que cambiaría tu recomendación. Un pequeño ensayo permitiría revisar conversión y tiempos. No presentes una preferencia imaginada como encuesta realizada ni un segmento como un conjunto de personas idénticas.'}
      ],
      example:{title:'Caso original ficticio: Rueda Clara',body:'Durante un mes, el segmento A contiene 200 clientes alcanzables y una conversión supuesta del 20 %: 40 servicios. Precio 30 €, coste variable 18 € y campaña 120 €: 40 × (30 − 18) − 120 = 360 €. B contiene 100 clientes, conversión del 30 %, precio 45 €, coste variable 25 € y campaña 150 €: 30 × 20 − 150 = 450 €. Ambos caben por separado en una capacidad de 45 servicios. B aporta 90 € más antes de costes comunes, pero si su conversión baja al 20 %, aporta 250 € y A resulta preferible.'},
      extension:'Evalúa una prueba dirigida a B con plazo de reparación garantizable. Explica qué dato recogerías y discute por qué mayor contribución prevista no demuestra mayor fidelidad. Mantén separados cálculos, supuestos y recomendación.',
      mistakes:['Confundir tamaño del segmento con compradores: aplicar una conversión justificada.','Llamar beneficio a la contribución tras campaña: todavía faltan costes comunes.','Prometer rapidez sin capacidad: comprobar recursos y plazos.'],
      glossary:[['Segmento','Grupo con características o necesidades relevantes compartidas.'],['Mercado objetivo','Segmento seleccionado para orientar la oferta y los recursos.'],['Posicionamiento','Percepción que se busca construir frente a las alternativas.'],['Contribución unitaria','Precio menos coste variable por unidad.']],
      refs:[{name:'OpenStax · Principles of Marketing, 5.6 Product Positioning (modelo STP; caso y cálculos originales)',url:'https://openstax.org/books/principles-marketing/pages/5-6-product-positioning',scope:'context',checked:'2026-10-18'}],
      quiz:[
        {text:L('¿Qué criterio orienta mejor el servicio urgente?','Which criterion best guides the urgent service?'),options:[L('Necesitar la bicicleta diariamente para desplazarse.','Needing the bicycle for daily travel.'),L('Tener un apellido corto.','Having a short surname.'),L('Suponer que todas las edades buscan lo mismo.','Assuming all ages want the same thing.')],answer:0,why:L('La necesidad de movilidad conecta con el valor de reducir la espera.','The mobility need connects to the value of reducing waiting time.'),optionWhy:[L('Permite adaptar plazos a una necesidad relevante.','It allows turnaround times to match a relevant need.'),L('No explica la necesidad de reparación urgente.','It does not explain the need for urgent repair.'),L('El supuesto elimina diferencias que deben investigarse.','The assumption removes differences that need investigation.')]},
        {text:L('¿Cuánto aporta B tras su campaña en el escenario inicial?','How much does B contribute after its campaign in the initial scenario?'),options:[L('600 €','€600'),L('450 €','€450'),L('1 350 €','€1,350')],answer:1,why:L('30 servicios × 20 € de contribución − 150 € de campaña = 450 €.','30 services × €20 contribution − €150 campaign cost = €450.'),optionWhy:[L('Es la contribución antes de restar la campaña.','This is contribution before subtracting the campaign cost.'),L('Incluye costes variables y campaña, pero no costes comunes.','It includes variable and campaign costs, but not shared costs.'),L('Son ingresos, antes de restar costes.','This is revenue before deducting costs.')]},
        {text:L('¿Qué conclusión evalúa los resultados?','Which conclusion evaluates the results?'),options:[L('B siempre será mejor.','B will always be better.'),L('A gana porque tiene más personas alcanzables.','A wins because it has more reachable people.'),L('B es preferible inicialmente; su conversión debe comprobarse.','B is initially preferable; its conversion rate needs checking.')],answer:2,why:L('La ventaja depende de una hipótesis que puede cambiar la decisión.','The advantage depends on an assumption that can change the decision.'),optionWhy:[L('La sensibilidad del ejemplo contradice esa certeza.','The sensitivity calculation contradicts that certainty.'),L('El tamaño por sí solo no determina la contribución.','Size alone does not determine contribution.'),L('Relaciona criterio, cálculo y limitación.','It connects a criterion, calculation and limitation.')]}
      ],
      practice:{prompt:L('Si la conversión de B es del 25 %, calcula su contribución tras campaña y evalúa B frente a A.','If B converts 25%, calculate its contribution after the campaign and evaluate B against A.'),steps:[L('Calcula compradores: 100 × 0,25.','Calculate buyers: 100 × 0.25.'),L('Multiplica por 45 − 25 y resta 150.','Multiply by 45 − 25 and subtract 150.'),L('Compara con 360 € de A y explica una limitación de la previsión.','Compare with A’s €360 and explain one forecasting limitation.')],checks:[L('Obtuve 350 € y una ventaja de 10 € para A.','I obtained €350 and a €10 advantage for A.'),L('No confundí contribución con beneficio total.','I did not confuse contribution with total profit.')],numeric:{value:350,tolerance:0.01,unit:'EUR'}}
    },
    {
      course:'business',id:'business-decisions',
      title:L('Decidir con criterios y análisis de sensibilidad','Deciding with criteria and sensitivity analysis'),
      intro:L('Compara dos métodos de producción de una empresa ficticia. Usa cálculos comparables y evidencia cualitativa para construir una recomendación condicionada.','Compare two production methods for a fictional business. Use comparable calculations and qualitative evidence to build a conditional recommendation.'),
      keywords:'business decisiones decisions explain analyse discuss evaluate costes sensibilidad stakeholders',difficulty:'intermediate',
      goals:['Aplicar criterios explícitos a alternativas.','Analizar cómo el volumen modifica los costes.','Construir una recomendación con límites y seguimiento.'],
      prerequisites:'Sustituir valores en expresiones lineales y reconocer costes fijos y variables.',
      sections:[
        {title:'Definir la decisión antes de calcular',body:'Una recomendación comienza con un objetivo y un periodo. La imprenta ficticia Pliego Sur necesita producir cuadernos durante un mes y compara dos métodos con la misma calidad exigida. Define qué puede cambiar y qué constituye una restricción: presupuesto disponible, entrega o capacidad. Después identifica alternativas viables, incluida una prueba limitada cuando sea posible. Explicar exige dar una razón aplicada al caso; enumerar ventajas generales no demuestra que resuelvan su problema. Una opción barata pierde relevancia si no puede entregar el volumen comprometido dentro del plazo acordado con clientes.'},
        {title:'Analizar relaciones y supuestos',body:'Para comparar costes, utiliza el mismo volumen y periodo en ambas opciones. El coste mensual será el cargo fijo más el coste variable por cuaderno multiplicado por la cantidad. Analizar significa mostrar cómo una diferencia produce consecuencias: un cargo fijo mayor puede compensarse mediante menor coste por unidad cuando aumenta el volumen. Declara qué conceptos están incluidos para no sumar dos veces alquiler o materiales. La demanda prevista no es una venta asegurada. Un análisis de sensibilidad cambia una hipótesis y comprueba si la preferencia se mantiene o se invierte.'},
        {title:'Discutir y evaluar alternativas',body:'Discutir requiere considerar argumentos relevantes a favor y en contra, como flexibilidad frente a dependencia del proveedor. Evaluar añade un juicio razonado según prioridades: el ahorro importa, pero también importan fiabilidad y capacidad de responder a cambios. Identifica qué evidencia falta sin inventar puntuaciones ni probabilidades. Una recomendación puede favorecer un método a cierto volumen y exigir una prueba de calidad antes de contratarlo. Define además cuándo revisar la decisión. Consultar a quienes producirán y recibirán los cuadernos ayuda a detectar costes y dificultades que una comparación numérica podría omitir.'}
      ],
      example:{title:'Caso original ficticio: Pliego Sur',body:'Para un mes, el método A cobra 600 € fijos más 4 € por cuaderno; B cobra 1 200 € más 2,50 €. Estos importes cubren todos los costes relevantes de la comparación y ambos admiten hasta 800 unidades. Con 300 unidades, A cuesta 1 800 € y B 1 950 €: A ahorra 150 €. Igualando 600 + 4q = 1 200 + 2,50q resulta q = 400. Es la indiferencia entre métodos, no el punto de equilibrio de beneficio. Con 600 unidades, A cuesta 3 000 € y B 2 700 €: B ahorra 300 €.'},
      extension:'Evalúa B si la demanda prevista es de 600 unidades pero existe riesgo de caer a 300. Discute ahorro, flexibilidad contractual y evidencia pendiente sobre entrega; termina con una condición concreta para revisar la elección.',
      mistakes:['Comparar opciones con volúmenes distintos: mantener una base común.','Llamar beneficio al ahorro: no se han dado ingresos.','Confundir indiferencia de costes con beneficio cero: son preguntas diferentes.'],
      glossary:[['Criterio','Aspecto usado para comparar alternativas según un objetivo.'],['Sensibilidad','Cambio de resultados al modificar una hipótesis.'],['Restricción','Condición que limita las alternativas viables.'],['Evaluar','Emitir un juicio sustentado en criterios, evidencia y limitaciones.']],
      refs:[{name:'OpenStax · Principles of Management, 2.5 Improving the Quality of Decision-Making (alternativas y evaluación; modelo numérico original)',url:'https://openstax.org/books/principles-management/pages/2-5-improving-the-quality-of-decision-making',scope:'context',checked:'2026-10-18'}],
      quiz:[
        {text:L('¿Qué significa q = 400 en este caso?','What does q = 400 mean in this case?'),options:[L('Los dos métodos obtienen beneficio cero.','Both methods earn zero profit.'),L('Los costes de los métodos son iguales.','The methods have equal costs.'),L('La demanda será exactamente 400.','Demand will be exactly 400.')],answer:1,why:L('La ecuación iguala dos costes; no incluye ingresos ni predice demanda.','The equation equates two costs; it neither includes revenue nor predicts demand.'),optionWhy:[L('No conocemos precios de venta para calcular beneficio.','Selling prices are unknown, so profit cannot be calculated.'),L('Ambos cuestan 2 200 € con 400 unidades.','Both cost €2,200 at 400 units.'),L('Es un umbral de comparación, no una previsión.','It is a comparison threshold, not a forecast.')]},
        {text:L('¿Qué cálculo corresponde a B con 600 unidades?','Which calculation describes B at 600 units?'),options:[L('1 200 + 2,50 × 600 = 2 700 €','1,200 + 2.50 × 600 = €2,700'),L('2,50 × 600 = 1 500 €','2.50 × 600 = €1,500'),L('600 + 4 × 600 = 3 000 €','600 + 4 × 600 = €3,000')],answer:0,why:L('Incluye el cargo fijo y el coste variable del método B.','It includes method B’s fixed charge and variable cost.'),optionWhy:[L('Utiliza todos los costes relevantes indicados para B.','It uses all relevant costs stated for B.'),L('Omite el cargo fijo de 1 200 €.','It omits the €1,200 fixed charge.'),L('Calcula el coste de A, no el de B.','It calculates A’s cost rather than B’s.')]},
        {text:L('¿Qué respuesta cumple mejor evaluar?','Which response best fulfils evaluate?'),options:[L('B tiene un coste variable.','B has a variable cost.'),L('B es mejor porque me gusta.','B is better because I like it.'),L('Elegir B con 600 unidades si confirma entrega; revisar si la demanda baja de 400.','Choose B at 600 units if delivery is confirmed; review if demand falls below 400.')],answer:2,why:L('Combina cálculo, criterio operativo y condición de revisión.','It combines a calculation, an operational criterion and a review condition.'),optionWhy:[L('Describe un dato sin juzgar alternativas.','It describes a fact without judging alternatives.'),L('La preferencia carece de evidencia aplicada.','The preference lacks applied evidence.'),L('Justifica la elección y reconoce qué podría cambiarla.','It justifies the choice and recognises what could change it.')]}
      ],
      practice:{prompt:L('Con 500 cuadernos, calcula cuánto ahorra B frente a A y redacta una recomendación condicionada.','At 500 notebooks, calculate B’s saving compared with A and write a conditional recommendation.'),steps:[L('Calcula A = 600 + 4 × 500.','Calculate A = 600 + 4 × 500.'),L('Calcula B = 1 200 + 2,50 × 500 y resta B a A.','Calculate B = 1,200 + 2.50 × 500 and subtract B from A.'),L('Explica el ahorro y discute una condición de entrega o calidad.','Explain the saving and discuss one delivery or quality condition.')],checks:[L('Comparé 2 600 € con 2 450 €: ahorro de 150 €.','I compared €2,600 with €2,450: a €150 saving.'),L('Mi recomendación distingue evidencia y datos pendientes.','My recommendation distinguishes evidence from missing information.')],numeric:{value:150,tolerance:0.01,unit:'EUR'}}
    },
    {
      course:'business',id:'business-cashflow',
      title:L('Tesorería: ventas, cobros y financiación','Cash flow: sales, receipts and financing'),
      intro:L('Construye una previsión mensual para una empresa ficticia y explica por qué el beneficio puede coexistir con falta de efectivo. Evalúa respuestas a un déficit temporal.','Build a monthly forecast for a fictional business and explain why profit can coexist with a cash shortage. Evaluate responses to a temporary deficit.'),
      keywords:'business cashflow cash flow tesorería flujo caja cobros pagos liquidez beneficio financiación estado resultados income statement',difficulty:'intermediate',
      goals:['Distinguir ventas de cobros y beneficio de efectivo.','Calcular flujo neto y saldo final mensual.','Evaluar medidas para cubrir un déficit temporal.'],
      prerequisites:'Sumar importes con signo y reconocer ingresos, gastos y préstamos.',
      sections:[
        {title:'Explicar el desfase entre vender y cobrar',body:'Una venta a crédito puede generar ingresos del periodo sin aportar efectivo hasta el mes siguiente. Por eso, el beneficio no indica por sí solo cuánto dinero hay para pagar nóminas. La empresa ficticia Lámpara Lila factura pedidos que sus clientes pagan después de recibirlos. Explica la cadena causal: el gasto se atiende antes de cobrar, el saldo disminuye y aparece una necesidad temporal de financiación. Tampoco un préstamo constituye ingreso por ventas: aumenta el efectivo y una obligación de devolución. Separar estas categorías evita interpretar financiación como éxito comercial.'},
        {title:'Construir una previsión consistente',body:'En una previsión de tesorería, registra cada cobro y pago en el periodo en que se espera que ocurra. Flujo neto es cobros menos pagos; saldo final es saldo inicial más flujo neto. El saldo final de un mes pasa a ser el inicial del siguiente, salvo que añadas explícitamente una nueva operación. No incluyas dos veces una factura al vender y al cobrar. Declara si existen impuestos, inversiones o intereses; aquí se excluyen para aislar el desfase. Un saldo final negativo representa una necesidad pendiente de cobertura, no efectivo disponible.'},
        {title:'Evaluar cómo cubrir la falta de efectivo',body:'Un déficit previsto puede abordarse acelerando cobros, negociando pagos o utilizando financiación acordada. Analiza efectos secundarios: un descuento reduce lo recibido, aplazar pagos exige acuerdo y un préstamo añade devoluciones e intereses. Discute también qué ocurre si un cliente paga tarde. Al evaluar, relaciona duración del déficit con la medida propuesta y comprueba el saldo posterior. Una previsión mensual positiva no descarta un problema dentro del mes si los pagos preceden a los cobros. Para decidir fechas de financiación haría falta una previsión más detallada y condiciones reales, todavía desconocidas en este caso.'}
      ],
      example:{title:'Caso original ficticio: Lámpara Lila',body:'En abril hay 800 € iniciales, ventas de 3 000 €, cobros de 1 200 € y pagos de 2 500 €. Todos esos pagos son gastos de abril; no hay otros gastos. Beneficio simplificado: 3 000 − 2 500 = 500 €. Flujo neto: 1 200 − 2 500 = −1 300 €; cierre sin financiación: 800 − 1 300 = −500 €. Un préstamo de 500 € deja cierre de 0 €. En mayo se cobran los 1 800 € pendientes y se pagan 1 000 € operativos y 500 € de principal: cierre 300 €, suponiendo intereses nulos solo en este ejercicio.'},
      extension:'Discute si financiar únicamente 500 € basta cuando el cobro de mayo puede retrasarse. Explica qué calendario adicional necesitas y evalúa negociar anticipos frente a pedir un préstamo mayor, sin inventar sus condiciones.',
      mistakes:['Registrar todas las ventas como cobros: respetar las fechas.','Contar el préstamo como ingreso comercial: separar financiación y ventas.','Restar la devolución del principal como gasto del beneficio: es un pago que reduce deuda.'],
      glossary:[['Liquidez','Capacidad de atender obligaciones de pago a su vencimiento.'],['Flujo neto','Diferencia entre entradas y salidas de efectivo de un periodo.'],['Saldo final','Efectivo inicial más el flujo neto del periodo.'],['Venta a crédito','Venta cuyo cobro se acuerda para una fecha posterior.']],
      refs:[{name:'SEC · Beginners’ Guide to Financial Statements (beneficio, efectivo y financiación; previsión ficticia original)',url:'https://www.sec.gov/about/reports-publications/investorpubsbegfinstmtguide',scope:'context',checked:'2026-10-18'}],
      quiz:[
        {text:L('¿Cuál es el saldo de abril antes del préstamo?','What is April’s balance before the loan?'),options:[L('500 €','€500'),L('−1 300 €','−€1,300'),L('−500 €','−€500')],answer:2,why:L('800 + 1 200 − 2 500 = −500 €.','800 + 1,200 − 2,500 = −€500.'),optionWhy:[L('Es el beneficio simplificado, no el saldo de caja.','This is simplified profit rather than the cash balance.'),L('Es el flujo neto y omite el saldo inicial.','This is net cash flow and omits the opening balance.'),L('Incluye saldo inicial, cobros y pagos.','It includes the opening balance, receipts and payments.')]},
        {text:L('¿Cómo afecta el préstamo de 500 € al recibirse?','What happens when the €500 loan is received?'),options:[L('Aumentan efectivo y deuda.','Cash and debt increase.'),L('Aumentan ventas y beneficio en 500 €.','Sales and profit increase by €500.'),L('Desaparecen los gastos de abril.','April’s expenses disappear.')],answer:0,why:L('Financia pagos sin convertir deuda en ventas.','It finances payments without turning debt into sales.'),optionWhy:[L('La entrada de efectivo genera una obligación de devolución.','The cash receipt creates a repayment obligation.'),L('Un préstamo no es ingreso por vender productos.','A loan is not revenue from selling products.'),L('Los gastos siguen existiendo aunque cambie su financiación.','Expenses remain even if their financing changes.')]},
        {text:L('¿Por qué un cierre mensual positivo puede ser insuficiente?','Why might a positive month-end balance be insufficient?'),options:[L('Porque todos los préstamos son ventas.','Because every loan is a sale.'),L('Porque algunos pagos pueden vencer antes de los cobros.','Because some payments may fall due before receipts arrive.'),L('Porque beneficio y caja siempre son iguales.','Because profit and cash are always equal.')],answer:1,why:L('El orden de movimientos dentro del mes también afecta a la liquidez.','The order of transactions within the month also affects liquidity.'),optionWhy:[L('Confunde financiación con actividad comercial.','It confuses financing with trading activity.'),L('Un saldo diario negativo puede quedar oculto en el total mensual.','A negative daily balance can be hidden by the monthly total.'),L('Las ventas a crédito del caso muestran su diferencia.','The case’s credit sales illustrate the difference.')]}
      ],
      practice:{prompt:L('En mayo se retrasan 400 € de los cobros hasta junio. Con apertura de 0 €, pagos operativos de 1 000 € y devolución de 500 €, calcula el cierre antes de nueva financiación y evalúa una respuesta.','In May, €400 of receipts are delayed until June. With an opening balance of €0, operating payments of €1,000 and a €500 repayment, calculate the closing balance before new financing and evaluate a response.'),steps:[L('Reduce los cobros de mayo: 1 800 − 400.','Reduce May’s receipts: 1,800 − 400.'),L('Resta los pagos operativos y la devolución del préstamo.','Subtract operating payments and loan repayment.'),L('Explica qué acuerdo sería necesario para cubrir el déficit y qué revisarías en junio.','Explain what agreement would cover the shortfall and what you would review in June.')],checks:[L('Obtuve −100 € antes de cualquier medida adicional.','I obtained −€100 before any additional measure.'),L('No presenté una prórroga o préstamo nuevo como ya aprobado.','I did not treat an extension or new loan as already approved.')],numeric:{value:-100,tolerance:0.01,unit:'EUR'}}
    },
    {
      course:'business',id:'business-break-even',
      title:L('Punto de equilibrio y margen de seguridad','Break-even point and margin of safety'),
      intro:L('Calcula cuántas unidades necesita vender un negocio ficticio para cubrir sus costes. Analiza cómo un descuento modifica el umbral y evalúa sus límites.','Calculate how many units a fictional business must sell to cover its costs. Analyse how a discount changes the threshold and evaluate its limitations.'),
      keywords:'business break even punto equilibrio umbral rentabilidad contribución margen seguridad fixed variable costs',difficulty:'intermediate',
      goals:['Calcular contribución, punto de equilibrio y margen de seguridad.','Comprobar el beneficio mediante ingresos y costes.','Evaluar un descuento bajo supuestos explícitos.'],
      prerequisites:'Dividir cantidades y distinguir coste fijo total de coste variable unitario.',
      sections:[
        {title:'Explicar la contribución',body:'Cada unidad vendida aporta su precio, pero también genera un coste variable. La diferencia es la contribución unitaria disponible para cubrir costes fijos y, después, obtener beneficio. En el negocio ficticio Taza Norte, materiales y embalaje varían con las unidades; el cargo fijo mensual permanece igual dentro de la capacidad indicada. Explicar esta relación evita llamar beneficio a todo el margen de una taza. Trabaja siempre con un mismo periodo y especifica qué costes incluye el modelo. Si el precio no supera el coste variable, vender más no cubre costes fijos positivos.'},
        {title:'Calcular e interpretar el umbral',body:'El punto de equilibrio en unidades se calcula dividiendo costes fijos entre contribución unitaria positiva. En ese volumen, los ingresos igualan los costes totales y el beneficio del modelo es cero. Si el resultado contiene una fracción y el producto es indivisible, redondea hacia arriba para identificar la primera cantidad sin pérdidas. El margen de seguridad compara ventas previstas o reales con el umbral; expresa cuánto podrían caer antes de entrar en pérdidas. Distingue unidades de euros y comprueba el resultado sustituyendo el volumen en la expresión del beneficio mensual.'},
        {title:'Evaluar una decisión comercial',body:'Un descuento reduce la contribución por unidad si el coste variable permanece igual. Para analizarlo, recalcula el umbral y comprueba cuántas ventas adicionales compensarían la reducción. No supongas que bajar el precio genera automáticamente esa demanda. Discute el atractivo para clientes y el riesgo de necesitar un volumen difícil de alcanzar. Evaluar requiere un juicio condicionado por capacidad y evidencia de ventas. El modelo supone precio y coste unitario constantes en el intervalo estudiado, y que se vende todo lo producido. Tampoco incorpora fechas de cobro: alcanzar equilibrio contable no garantiza liquidez.'}
      ],
      example:{title:'Caso original ficticio: Taza Norte',body:'Taza Norte vende un único producto a 20 €, con coste variable de 8 €, costes fijos mensuales de 1 800 € y capacidad de 240 unidades. Contribución: 12 €; equilibrio: 1 800 ÷ 12 = 150 unidades. Con ventas previstas de 200, beneficio: 200 × 12 − 1 800 = 600 €; margen de seguridad: 50 unidades, o 50 ÷ 200 × 100 = 25 %. A un precio de 18 €, la contribución baja a 10 €, el equilibrio sube a 180 y, vendiendo 200, el beneficio cae a 200 €. Para conservar 600 € habría que vender 240 unidades.'},
      extension:'Evalúa el descuento si vender 240 unidades utiliza toda la capacidad. Explica por qué recuperar el beneficio inicial exige más que superar el nuevo equilibrio y qué evidencia de demanda pedirías antes de recomendarlo.',
      mistakes:['Dividir costes fijos entre precio: restar primero el coste variable unitario.','Confundir equilibrio con beneficio objetivo: añadir el beneficio deseado al numerador.','Usar el equilibrio como denominador del margen porcentual: dividir por ventas previstas o reales.'],
      glossary:[['Coste fijo','Coste total que permanece constante dentro del intervalo considerado.'],['Contribución','Ingresos menos costes variables, disponibles para cubrir costes fijos y beneficio.'],['Punto de equilibrio','Volumen donde ingresos y costes totales son iguales.'],['Margen de seguridad','Exceso de ventas sobre las ventas de equilibrio.']],
      refs:[{name:'OpenStax · Managerial Accounting, 3.2 Calculate a Break-Even Point in Units and Dollars (fórmulas; caso original)',url:'https://openstax.org/books/principles-managerial-accounting/pages/3-2-calculate-a-break-even-point-in-units-and-dollars',scope:'context',checked:'2026-10-18'}],
      quiz:[
        {text:L('¿Cuál es el equilibrio con el precio inicial?','What is break-even at the initial price?'),options:[L('90 unidades','90 units'),L('150 unidades','150 units'),L('225 unidades','225 units')],answer:1,why:L('1 800 ÷ (20 − 8) = 150 unidades.','1,800 ÷ (20 − 8) = 150 units.'),optionWhy:[L('Divide entre precio e ignora costes variables.','It divides by price and ignores variable costs.'),L('Utiliza la contribución de 12 € por unidad.','It uses the €12 contribution per unit.'),L('Divide entre coste variable en vez de contribución.','It divides by variable cost instead of contribution.')]},
        {text:L('¿Qué representa el margen de seguridad inicial de 50 unidades?','What does the initial 50-unit margin of safety represent?'),options:[L('Las ventas pueden caer de 200 a 150 antes de generar pérdidas.','Sales can fall from 200 to 150 before generating losses.'),L('Cada taza genera 50 € de beneficio.','Each mug generates €50 profit.'),L('La capacidad máxima es 50 unidades.','Maximum capacity is 50 units.')],answer:0,why:L('Es la diferencia entre ventas previstas y volumen de equilibrio.','It is the difference between forecast sales and break-even volume.'),optionWhy:[L('Mantiene las unidades y los supuestos del modelo.','It preserves the model’s units and assumptions.'),L('Confunde una cantidad de productos con un importe.','It confuses a product quantity with a monetary amount.'),L('La capacidad indicada es de 240 unidades.','The stated capacity is 240 units.')]},
        {text:L('¿Qué exige mantener 600 € de beneficio tras el descuento?','What is needed to maintain €600 profit after the discount?'),options:[L('Vender 180 unidades.','Sell 180 units.'),L('Vender las mismas 200 unidades.','Sell the same 200 units.'),L('Vender 240 unidades.','Sell 240 units.')],answer:2,why:L('(1 800 + 600) ÷ 10 = 240 unidades.','(1,800 + 600) ÷ 10 = 240 units.'),optionWhy:[L('180 unidades solo cubren costes con el nuevo precio.','180 units only cover costs at the new price.'),L('200 unidades producen 200 € de beneficio.','200 units produce €200 profit.'),L('La contribución total de 2 400 € cubre costes fijos y objetivo.','Total contribution of €2,400 covers fixed costs and the target.')]}
      ],
      practice:{prompt:L('Manteniendo precio de 20 € y costes fijos de 1 800 €, el coste variable sube a 9 €. Calcula las unidades enteras mínimas sin pérdidas y evalúa el cambio.','Keeping the €20 price and €1,800 fixed costs, variable cost rises to €9. Calculate the minimum whole units without a loss and evaluate the change.'),steps:[L('Calcula la nueva contribución: 20 − 9.','Calculate the new contribution: 20 − 9.'),L('Divide 1 800 entre esa contribución y redondea hacia arriba.','Divide 1,800 by that contribution and round up.'),L('Comprueba el beneficio con 163 y 164 unidades y compara el riesgo con el caso inicial.','Check profit at 163 and 164 units and compare the risk with the original case.')],checks:[L('Obtuve 164 unidades: 163 generan −7 € y 164 generan 4 €.','I obtained 164 units: 163 generate −€7 and 164 generate €4.'),L('Expliqué por qué el umbral mayor reduce el margen de seguridad.','I explained why the higher threshold reduces the margin of safety.')],numeric:{value:164,tolerance:0,unit:'unidades / units'}}
    },
    {
      course:'business',id:'business-motivation',
      title:L('Motivación, incentivos y calidad del trabajo','Motivation, incentives and work quality'),
      intro:L('Analiza un incentivo en un taller ficticio utilizando productividad y calidad. Discute recompensas, autonomía y equidad antes de recomendar una prueba.','Analyse an incentive in a fictional workshop using productivity and quality. Discuss rewards, autonomy and fairness before recommending a trial.'),
      keywords:'business motivation motivación incentivos expectancy expectativa equidad productividad calidad autonomía',difficulty:'intermediate',
      goals:['Explicar cómo un incentivo podría orientar el esfuerzo.','Calcular productividad ajustada por calidad.','Evaluar una intervención sin atribuir causalidad injustificada.'],
      prerequisites:'Calcular tasas y porcentajes y distinguir una hipótesis de un resultado observado.',
      sections:[
        {title:'Explicar mecanismos de motivación',body:'La motivación ayuda a explicar hacia dónde se dirige el esfuerzo y por qué se sostiene. Un incentivo puede resultar atractivo si la persona valora la recompensa, cree que puede alcanzar el desempeño requerido y confía en que recibirá lo prometido. Estas relaciones no son automáticas: faltas de formación o herramientas pueden impedir cumplir una meta. En el taller ficticio Nido Papel, pagar por cantidad podría dirigir la atención hacia rapidez. Explicar ese mecanismo no equivale a afirmar que todas las personas responderán igual ni que el dinero sea su única motivación.'},
        {title:'Analizar resultados sin perder la calidad',body:'Para analizar una medida, define qué cuenta como resultado útil. El volumen bruto puede crecer mientras aumentan los errores; por eso el caso calcula unidades aceptadas por hora, manteniendo comparable el producto. Un indicador necesita contexto: dificultad de pedidos, materiales y experiencia del equipo también pueden cambiar. La comparación entre dos semanas no demuestra por sí sola que el incentivo causó la diferencia. Registra qué hipótesis se pretende comprobar y qué otras explicaciones serían posibles. No traduzcas automáticamente mayor producción en mayor beneficio sin conocer precios, costes y el importe de las recompensas.'},
        {title:'Discutir equidad y evaluar una prueba',body:'Discute beneficios y límites de combinar objetivos claros, formación, reconocimiento y autonomía para organizar tareas. Un premio individual puede percibirse como injusto si unas personas reciben pedidos fáciles y otras resuelven problemas complejos. Un premio colectivo puede favorecer cooperación, aunque requiere criterios transparentes sobre aportaciones. Evalúa una prueba con duración y revisión definidas: consulta al equipo, compara calidad y tiempos y comprueba si la meta sigue siendo alcanzable. La recomendación debe reconocer diferencias personales y condiciones de trabajo. No presentes una teoría como receta universal ni inventes testimonios de empleados para sostenerla.'}
      ],
      example:{title:'Caso original ficticio: Nido Papel',body:'Datos inventados de dos semanas con 40 horas de trabajo cada una. Antes del incentivo se terminan 200 unidades y se rechazan 10: 190 aceptadas, o 4,75 por hora. Durante la prueba se terminan 240 y se rechazan 36: 204 aceptadas, o 5,10 por hora. El volumen bruto crece 20 %, pero la productividad aceptada crece (5,10 − 4,75) ÷ 4,75 × 100 ≈ 7,37 %. La tasa de rechazo sube del 5 % al 15 %. Hay más unidades útiles, pero también un problema de calidad; faltan costes y control de otras variables para juzgar rentabilidad y causalidad.'},
      extension:'Evalúa sustituir la meta de volumen por una meta de unidades aceptadas con apoyo formativo. Discute cómo evitar ocultar defectos y qué datos de dificultad de pedidos y percepción de equidad recogerías durante la prueba.',
      mistakes:['Identificar motivación con dinero exclusivamente: considerar qué valora cada persona.','Medir solo volumen bruto: incluir unidades aceptadas y rechazos.','Atribuir toda diferencia al incentivo: examinar otras variables.'],
      glossary:[['Expectativa','Creencia de que el esfuerzo puede producir el desempeño requerido.'],['Instrumentalidad','Creencia de que el desempeño permitirá obtener la recompensa.'],['Valencia','Valor que una persona atribuye a una recompensa.'],['Productividad','Producción obtenida por unidad de recurso utilizado.'],['Equidad percibida','Valoración de la justicia de aportaciones y recompensas.']],
      refs:[{name:'OpenStax · Principles of Management, 14 Introduction (contexto de motivación)',url:'https://openstax.org/books/principles-management/pages/14-introduction',scope:'context',checked:'2026-10-18'},{name:'OpenStax · Principles of Management, 14.3 Process Theories of Motivation (expectativa y equidad; datos originales)',url:'https://openstax.org/books/principles-management/pages/14-3-process-theories-of-motivation',scope:'context',checked:'2026-10-18'}],
      quiz:[
        {text:L('¿Cuál es la productividad aceptada durante la prueba?','What is accepted-output productivity during the trial?'),options:[L('6 unidades por hora','6 units per hour'),L('0,90 unidades por hora','0.90 units per hour'),L('5,10 unidades por hora','5.10 units per hour')],answer:2,why:L('(240 − 36) ÷ 40 = 5,10 unidades aceptadas por hora.','(240 − 36) ÷ 40 = 5.10 accepted units per hour.'),optionWhy:[L('Cuenta producción bruta, incluidos rechazos.','It counts gross output, including rejected units.'),L('Mide rechazos por hora, no unidades aceptadas.','It measures rejections per hour, not accepted units.'),L('Descuenta rechazos antes de dividir por horas.','It subtracts rejections before dividing by hours.')]},
        {text:L('¿Qué puede debilitar la expectativa de alcanzar la meta?','What can weaken the expectation of meeting the target?'),options:[L('No disponer de formación ni herramientas adecuadas.','Lacking appropriate training and tools.'),L('Conocer claramente la meta.','Knowing the target clearly.'),L('Tener los recursos necesarios.','Having the necessary resources.')],answer:0,why:L('El esfuerzo puede parecer insuficiente si faltan medios para realizar el trabajo.','Effort may seem insufficient when the means to do the work are missing.'),optionWhy:[L('Puede romper la relación percibida entre esfuerzo y desempeño.','It can weaken the perceived link between effort and performance.'),L('La claridad ayuda a comprender el desempeño requerido.','Clarity helps people understand the required performance.'),L('Los recursos pueden facilitar alcanzar la meta.','Resources can help people achieve the target.')]},
        {text:L('¿Qué conclusión está mejor respaldada?','Which conclusion is best supported?'),options:[L('El incentivo causó por sí solo todos los cambios.','The incentive alone caused every change.'),L('Aumentó la producción aceptada, pero deben investigarse calidad y otras causas.','Accepted output increased, but quality and other causes need investigation.'),L('El beneficio creció exactamente un 20 %.','Profit rose by exactly 20%.')],answer:1,why:L('Describe los datos y limita las inferencias que permiten.','It describes the data and limits the inferences they allow.'),optionWhy:[L('Dos semanas sin controlar variables no establecen esa causalidad.','Two weeks without controlling variables do not establish that causality.'),L('Reconoce la mejora útil y el aumento de rechazos.','It recognises useful improvement and increased rejections.'),L('No hay información suficiente sobre ingresos y costes.','There is insufficient information about revenue and costs.')]}
      ],
      practice:{prompt:L('Una nueva semana ficticia produce 220 unidades, rechaza 11 y utiliza 40 horas. Calcula productividad aceptada y evalúa su calidad frente a la primera prueba.','A new fictional week produces 220 units, rejects 11 and uses 40 hours. Calculate accepted-output productivity and evaluate quality against the first trial.'),steps:[L('Resta rechazos y divide unidades aceptadas entre horas.','Subtract rejections and divide accepted units by hours.'),L('Calcula 11 ÷ 220 × 100 y compara con el 15 % de rechazo anterior.','Calculate 11 ÷ 220 × 100 and compare with the previous 15% rejection rate.'),L('Discute si recomendarías continuar y qué variables faltan para atribuir causas.','Discuss whether you would recommend continuing and what variables are missing for causal attribution.')],checks:[L('Obtuve 5,225 unidades aceptadas por hora y 5 % de rechazo.','I obtained 5.225 accepted units per hour and a 5% rejection rate.'),L('Comparé calidad y productividad sin afirmar un efecto causal demostrado.','I compared quality and productivity without claiming a proven causal effect.')],numeric:{value:5.225,tolerance:0.001,unit:'unidades/h / units/h'}}
    }
  ]);
})();
